package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.lianxibu.site.service.jobs.WorkerAuthorizationService.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/** Only scope boundaries with real shared transactions; network is a fictional callback. */
class WorkerProofCaptureBoundaryTest {
    GenerationJdbcStoreTest f;Store original,claimScope,sendScope;WorkerAuthorizationService service;Clock clock;AtomicInteger captured;
    final String hash="a".repeat(64),request="{\"provider\":\"deepseek\",\"model\":\"deepseek-flash\",\"messages\":[{\"role\":\"user\",\"content\":\"Fictional boundary verification\"}],\"parameters\":{},\"response_format\":{\"type\":\"json_object\"},\"schema_version\":\"v1\",\"prompt_version\":\"v1\",\"input_hash\":\""+hash+"\"}";
    @BeforeEach void setup(){f=new GenerationJdbcStoreTest();f.fixture();clock=Clock.fixed(Instant.parse("2026-01-01T18:00:00Z"),ZoneOffset.UTC);original=mock(Store.class);claimScope=mock(Store.class);sendScope=mock(Store.class);captured=new AtomicInteger();when(original.committedAbort(any())).thenReturn(null);when(original.captureClaim(any(),any())).thenAnswer(c->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());captured.incrementAndGet();return claimScope;});when(original.captureAuthorization(any())).thenAnswer(c->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());captured.incrementAndGet();return sendScope;});when(claimScope.slotFree()).thenReturn(true);when(claimScope.candidates(any())).thenAnswer(c->{writer();return List.of(new Candidate("fictional-root","fictional-attempt",2,clock.instant(),"queued","prepared",true,0,3,request,hash,0));});when(claimScope.reserve(any(),any(),any(),any(),any())).thenAnswer(c->{writer();return new Identity("fictional-root","fictional-attempt","fictional-token",1,1,clock.instant().plusSeconds(150),request,hash);});when(sendScope.authorize(any(),any(),any())).thenAnswer(c->{writer();return new Authorization(true,null);});service=new WorkerAuthorizationService(f.writes,original,clock,n->0,()->true);}
    void writer(){assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertFalse(TransactionSynchronizationManager.isCurrentTransactionReadOnly());}
    SharedWriteExecutor.ActionContext action(){return new SharedWriteExecutor.ActionContext("fictional-capture-claim","fictional-root",hash);}
    @Test void BothScopesAreCapturedOutsideAndConsumedOnlyInTheirOriginalWriters(){var claim=service.claim(action());assertEquals(State.CLAIMED,claim.state());AtomicInteger sent=new AtomicInteger();assertEquals(State.SENT,service.dispatch(claim.permit(),json->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());assertEquals(request,json);sent.incrementAndGet();return "fictional-result";}).state());assertEquals(2,captured.get());assertEquals(1,sent.get());verify(original,never()).candidates(any());verify(original,never()).reserve(any(),any(),any(),any(),any());verify(original,never()).authorize(any(),any(),any());assertEquals(State.LOST,service.dispatch(claim.permit(),json->{fail("must send at most once");return null;}).state());}
    @Test void ClaimCaptureFailureAndTypedCapacityReserveNothing(){when(original.captureClaim(any(),any())).thenThrow(new GenerationFlowService.CapacityGuarded());assertThrows(GenerationFlowService.CapacityGuarded.class,()->service.claim(action()));verifyNoInteractions(claimScope,sendScope);assertEquals(0,f.count("target_type IN ('worker_claim','worker_send')"));doReturn(null).when(original).captureClaim(any(),any());assertThrows(RuntimeException.class,()->service.claim(action()));verify(original,never()).reserve(any(),any(),any(),any(),any());}
    @Test void AuthorizationCaptureFailureCannotSendOrRefundAnUncertainPriorAuthorization(){var claim=service.claim(action());when(original.captureAuthorization(any())).thenThrow(new IllegalStateException("fictional capture unavailable"));assertEquals(State.UNKNOWN,service.dispatch(claim.permit(),json->{fail("proof failure must not send");return null;}).state());verifyNoInteractions(sendScope);verify(original,never()).refundNotSent(any(),any(),any(),any());verify(original,never()).committedAuthorization(any());}
    @Test void OutsideWindowAndCancellationKeepTheirOriginalNoCapturePaths(){var outside=new WorkerAuthorizationService(f.writes,original,Clock.fixed(Instant.parse("2026-01-01T10:00:00Z"),ZoneOffset.UTC),n->0,()->true);assertEquals(State.IDLE,outside.claim(action()).state());verifyNoInteractions(original);var claim=service.claim(action());claim.permit().cancelBeforeSend();when(original.refundNotSent(any(),any(),any(),any())).thenReturn(true);assertEquals(State.NOT_SENT,service.dispatch(claim.permit(),json->{fail("cancelled request must not send");return null;}).state());verify(original,never()).captureAuthorization(any());assertEquals(1,captured.get());}
}
